// 1. Obtener catálogo de CISA KEV (para detectar explotación activa)
const cisaNodeData = $('Fetch_CISA_KEV').first().json;
const cisaCatalog = cisaNodeData.vulnerabilities || [];

return items.map(inputItem => {
    const item = inputItem.json;

    // Si no hay asset_name es porque el JOIN de Postgres no encontró el activo en tu inventario
    if (!item.asset_name) return null; 

    // --- 1. LÓGICA DE VERSIONES (Tu código original) ---
    const vData = item.vulnerabilities || {};
    const miVersion = item.version || "0.0.0";
    const parcheVersion = vData.first_patched_version;

    let esVulnerableReal = true;
    if (parcheVersion && miVersion !== "0.0.0") {
        // Si la versión instalada ya es igual o mayor a la que trae el parche, ya no es vulnerable
        if (miVersion.localeCompare(parcheVersion, undefined, { numeric: true }) >= 0) {
            esVulnerableReal = false; 
        }
    }
    if (!esVulnerableReal) return null;

    // --- 2. EXTRACCIÓN DE DATOS TÉCNICOS ---
    const cvssScore = parseFloat(
        item.cvss_severities?.cvss_v4?.score || 
        item.cvss_severities?.cvss_v3?.score || 
        0.0
    );
    const idCve = item.cve_id || "N/A";
    const idGhsa = item.ghsa_id || "N/A";

    // Match con CISA KEV
    const cisaMatch = (idCve !== "N/A") 
        ? cisaCatalog.find(v => v.cveID?.trim().toUpperCase() === idCve.trim().toUpperCase()) 
        : null;
    const esExplotado = !!cisaMatch;

    // --- 3. MATRIZ DE RIESGO CONTEXTUAL ---
    let prioridadBase = "LOW";
    if (cvssScore >= 9.0) prioridadBase = "CRITICAL";
    else if (cvssScore >= 7.0) prioridadBase = "HIGH";
    else if (cvssScore >= 4.0) prioridadBase = "MEDIUM";

    const criticidadNegocio = item.env_criticality || "LOW";
    const entornoNombre = item.env_name || "DESCONOCIDO";
    let prioridadFinal = prioridadBase;

    // Ajuste de Prioridad según el Entorno (Lógica de Tesis)
    if (criticidadNegocio === "CRITICAL") {
        if (prioridadBase === "HIGH") prioridadFinal = "CRITICAL";
        if (prioridadBase === "MEDIUM") prioridadFinal = "HIGH";
    } else if (criticidadNegocio === "LOW") {
        if (prioridadBase === "CRITICAL") prioridadFinal = "HIGH";
        if (prioridadBase === "HIGH") prioridadFinal = "MEDIUM";
    }

    // --- 4. OVERRIDES DE SEGURIDAD ---
    // Si es CISA KEV: Escala a Crítico en PROD/QA y Alto en DESA
    if (esExplotado) {
        prioridadFinal = (criticidadNegocio === "LOW") ? "HIGH" : "CRITICAL";
    }

    // Si es Zero-Day (No hay parche disponible), subimos la urgencia un nivel
    const esZeroDay = !parcheVersion;
    if (esZeroDay) {
        if (prioridadFinal === "HIGH") prioridadFinal = "CRITICAL";
        else if (prioridadFinal === "MEDIUM") prioridadFinal = "HIGH";
        else if (prioridadFinal === "LOW") prioridadFinal = "MEDIUM";
    }

    // --- 5. ACTION PLAN CONTEXTUALIZADO ---
    let plan = "";
    if (esExplotado) {
        plan = `🚨 EMERGENCIA (CISA KEV) en ${entornoNombre}: Explotación activa detectada. AISLAR '${item.asset_name}' y aplicar parche v${parcheVersion || 'URGENTE'}.`;
    } 
    else if (esZeroDay) {
        plan = `💀 ZERO-DAY en ${entornoNombre}: No existe parche para '${item.software}'. Mitigar con reglas de red y monitoreo en '${item.asset_name}'.`;
    }
    else if (prioridadFinal === "CRITICAL") {
        plan = `⚠️ PRIORIDAD MÁXIMA: Activo crítico en ${entornoNombre}. Remediación requerida en menos de 24hs.`;
    }
    else {
        plan = `🔍 TRIAGE: Riesgo ${prioridadFinal.toLowerCase()} en ${entornoNombre}. Actualizar a v${parcheVersion} según ventana de mantenimiento.`;
    }

    // --- 6. SALIDA FINAL ---
    return {
        json: {
            asset_id: item.id,
            asset_name: item.asset_name,
            software: item.software,
            ecosystem: item.ecosystem,
            version_instalada: miVersion,
            patch_version: parcheVersion || "N/A",
            environment: entornoNombre,
            ghsa_id: idGhsa,
            cve_id: idCve,
            cvss: cvssScore,
            priority: prioridadFinal,
            is_cisa_kev: esExplotado,
            is_zero_day: esZeroDay,
            action_plan: plan,
            processed_at: new Date().toISOString()
        }
    };
}).filter(x => x !== null);

const allItems = items;

let metrics = {
    total_items: allItems.length,
    auditados: 0,
    ignorados: 0,
    criticos: 0,
    altas: 0,
    medias: 0,
    bajas: 0
};

// Objeto para agrupar las estadísticas por entorno
let stats_por_entorno = {};

for (const item of allItems) {
    const data = item.json;

    // Detectamos la prioridad (soporta varias fuentes de nombre)
    const rawPriority = data.priority || data.Priority || data.criticality || null;
    // Detectamos el entorno
    const envName = data.environment || data.env_name || "DESCONOCIDO";

    // Si encontramos una prioridad, el ítem fue analizado por el motor de riesgo
    if (rawPriority !== null) {
        metrics.auditados++;
        const sev = rawPriority.toString().toUpperCase();

        // 1. Inicializar el entorno en el objeto si no existe
        if (!stats_por_entorno[envName]) {
            stats_por_entorno[envName] = { 
                criticos: 0, 
                altas: 0, 
                medias: 0, 
                bajas: 0, 
                total: 0 
            };
        }

        // 2. Sumar al contador del entorno específico
        stats_por_entorno[envName].total++;

        // 3. Clasificar por severidad (Global y por Entorno)
        if (sev === 'CRITICAL') {
            metrics.criticos++;
            stats_por_entorno[envName].criticos++;
        } 
        else if (sev === 'HIGH') {
            metrics.altas++;
            stats_por_entorno[envName].altas++;
        } 
        else if (sev === 'MEDIUM') {
            metrics.medias++;
            stats_por_entorno[envName].medias++;
        } 
        else if (sev === 'LOW') {
            metrics.bajas++;
            stats_por_entorno[envName].bajas++;
        }
    } 
    // Si no tiene prioridad, es porque fue filtrado/ignorado antes del motor de riesgo
    else {
        metrics.ignorados++;
    }
}

return [{
    json: {
        ejecucion_stats: {
            resumen: `Análisis finalizado: ${metrics.total_items} registros evaluados.`,
            detalle: metrics,
            entornos: stats_por_entorno,
            status_sistema: metrics.criticos > 0 ? "⚠️ ACCIÓN REQUERIDA" : "✅ ESTABLE",
            fecha: new Date().toLocaleString('es-AR')
        }
    }
}];

