// 1. Recolección y limpieza de datos
const pool = [];

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;

  if (data.vulnerabilities && Array.isArray(data.vulnerabilities)) {
    const list = data.vulnerabilities;
    for (let j = 0; j < list.length; j++) {
      const v = list[j];
      if (v.package && v.package.name) {
        pool.push({
          name: v.package.name,
          ecosystem: v.package.ecosystem || "npm",
          summary: data.summary || "Simulación de seguridad",
          severity: data.severity || "CRITICAL",
          range: String(v.vulnerable_version_range || "0.0.1")
        });
      }
    }
  }
}

if (pool.length === 0) return [];

const selected = pool[Math.floor(Math.random() * pool.length)];
const envId = Math.floor(Math.random() * 3) + 1;

// 2. Extracción de versión UNICA (Corregido para evitar duplicados)
let versionStr = "0.0.1";
if (selected.range) {
  // Buscamos la primera secuencia de números y puntos
  const match = selected.range.match(/\d+[\d\.]*/);
  if (match) {
    // Tomamos match que es el string exacto encontrado, sin grupos de captura
    versionStr = String(match);

    // Limpieza extra: Si terminó en punto o coma por error, lo quitamos
    if (versionStr.endsWith('.') || versionStr.endsWith(',')) {
      versionStr = versionStr.slice(0, -1);
    }
  }
}

// 3. Retorno del objeto final
return [
  {
    json: {
      name: "ASSET-" + selected.name.toUpperCase(),
      software: selected.name.toLowerCase().trim(),
      ecosystem: selected.ecosystem.toLowerCase().trim(),
      version: versionStr, // Ahora sí: "16.0.5"
      criticality: selected.severity,
      last_scan: new Date().toISOString(),
      description: "Inyectado en Entorno ID " + envId + ": " + selected.summary,
      environment_id: envId
    }
  }
];
